/* The rooms (the rooms design): one spec `rooms` = { schema, source, order, rooms: { "<room>": { base, near, bed?, levels, joins, pieces, ambient } } } from ui/specs/station/rooms.json (generated by place-masters --rooms,
   in painting coordinates), merged by the host as `moving` is. The loader (room.c) checks it whole when it arrives and refuses it with a `wire_error`: the data guards 1 to 3 and 6 again (profiles, the draw-order invariant, the
   joins' ends on their levels, at most six occluders and 15 % of the window). The screens read it through the calls below; none of them reads the spec itself. Levels, joins and the walk on them come in R4 (room_on, room_point,
   room_route); this module is what R3 needs: the room chosen for a window, its back and occluder pieces in that window's coordinates, and the keep-outs of its pieces. */
#ifndef ROOM_H
#define ROOM_H
enum { RP_BACK = 1, RP_OCCLUDER = 2 };
/* A piece in a window's coordinates (the painting's plus the offset room_select was given). `pic` is the picture the props name for it (regions.room.pieces.<id>), "" when the props name none. `foot` is an occluder's sorting row
   (the window's); `opa` is a back piece's opacity (255 when the spec sets none). */
typedef struct { char id[32]; int kind; char pic[96]; int x, y, w, h, foot, opa; } rp_t;
/* The `rooms` spec arrived: check it whole and build the tables. 0, or -1 with the reason in err (the spec is then refused). */
int room_load(char *err, int cap);
/* Choose the room `id` for the window drawn now, with the offset (dx, dy) of the window from the painting (window = painting + offset), and read the props' piece pictures. main_only: the window uses the main level alone (Home).
   0, or -1 for an unknown room (the first room of the spec is used then); also -1, with no room chosen (no pieces, no keep-outs), when no spec is loaded or `id` is empty (props that name no room). */
int room_select(const char *id, int dx, int dy, int main_only);
/* The levels usable on the window chosen (1 when main_only). */
int room_levels(void);
/* The selected room's pieces of `kind` that have a picture (a null picture is a keep-out alone), in the window's coordinates, in data order. Returns their number; *out points at them until the next room_select. */
int room_pieces(int kind, const rp_t **out);
/* Whether the ground point (fx, feet), in the window's coordinates, stands in a piece's keep-out (the occluders' keep-outs, kept by their level). The bed's keep-out keeps its box rule in home.c. */
int room_keep(int fx, int feet);
#endif
